def fig_ma():
    X=lambda b:50+b*27;Y=lambda m:205-m*8.75
    o=L(50,205,330,205)+L(50,20,50,205)+'<line x1="%d" y1="%.1f" x2="%d" y2="%.1f" class="lna"/>'%(X(0),Y(4),X(10),Y(20))
    o+=L(50,Y(4),X(10),Y(4),'ln dash')+L(50,Y(12),X(5),Y(12),'ln dash')+L(X(5),Y(12),X(5),205,'ln dash')+C(X(5),Y(12),4,'hda')
    for m in (4,12,20):o+=TR(46,Y(m)+4,str(m),'t-s')
    for b in (0,5,10):o+=T(X(b),220,str(b),'t-s')
    o+=TL(58,26,'ток, мА','t-s t-b')+TL(240,200,'қысым, бар','t-s t-b').replace('y="200"','y="198"')
    o+=TL(X(5)+8,Y(12)+16,'12 мА → 5 бар','t-s ac')+TL(58,Y(2)+4,'< 4 мА — сым үзілген','t-s mu')
    return S(340,230,o,'Датчиктің 4–20 мА шығысы мен қысым арасындағы сызықтық байланыс')
